# Runtime v2 · PF Hiệu năng và debug (chương mới)
# Nguồn: "Compose performance", "Follow best practices", "Composition tracing", "Baseline Profiles", "Debug your Compose UI" (recomposition counts),
# "Tools for performance" (developer.android.com, đọc 2026-11-23); Kunneth Ch.10 (Layout Inspector); ComputedState.kt có trong thư mục runtime @296313a4.

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    # ---------------- sim runtime.perf ----------------
    m = lambda k, vi, en=None: a('m.perf.' + k, vi, en)
    m('title', 'Đếm recomposition: đọc thẳng, derivedStateOf, ghi ngược', 'Counting recompositions: direct reads, derivedStateOf, backwards writes')
    m('overview', 'Ba đoạn mã của trang Best practices. Hai đoạn đầu hiện nút "lên đầu" khi danh sách đã cuộn: một đọc thẳng `firstVisibleItemIndex` trong composition, một bọc trong `derivedStateOf`. Đoạn thứ ba ghi `count++` ngay trong thân composable. Đi qua bốn sự kiện và đếm số lần màn hình recompose.', 'Three snippets from the Best practices page. The first two show a "back to top" button once the list has scrolled: one reads `firstVisibleItemIndex` directly in composition, one wraps it in `derivedStateOf`. The third writes `count++` right in the composable body. Walk through four events and count how often the screen recomposes.')
    m('wrapup', 'Đọc một state đổi liên tục ngay trong composition sẽ làm recompose mỗi lần nó đổi, kể cả khi thứ bạn thật sự cần (một Boolean) không đổi. `derivedStateOf` lọc lại: chỉ khi kết quả đổi mới invalidate.\nGhi vào một state đã đọc trong cùng lượt composition ("ghi ngược") tạo ra vòng lặp recompose không dừng. Cả ba hiện tượng đều thấy được qua số đếm recompose của Layout Inspector, nhưng tài liệu nhắc: số đếm không thay được benchmark.\nQuy tắc dễ nhớ: đọc đúng chỗ, lọc đúng lúc, và không bao giờ ghi ngược.',
      'Reading a constantly changing state right in composition recomposes every time it changes, even when what you really need (a Boolean) does not change. `derivedStateOf` filters: only a change in the result invalidates.\nWriting to a state already read in the same composition pass (a "backwards write") creates a recomposition loop that never stops. All three show up in the Layout Inspector\'s recomposition counts, but the docs remind you: counts are no substitute for benchmarks.\nRule of thumb: read in the right place, filter at the right time, and never write backwards.')
    m('simp.1', 'Mỗi sự kiện là một lần đổi index (hoặc một frame với ghi ngược); danh sách thật có thể đổi index nhiều lần mỗi frame, và recompose được gom theo frame (chương B5).', 'Each event is one index change (or one frame for the backwards write); a real list may change its index several times per frame, and recompositions are batched per frame (chapter B5).')
    m('simp.2', 'Mô hình chỉ đếm recompose của "màn hình" chứa đoạn mã; với ghi ngược, mô phỏng dừng sau bốn lượt dù vòng lặp thật không dừng.', 'The model only counts recompositions of the "screen" holding the snippet; for the backwards write, the simulation stops after four passes even though the real loop never ends.')
    m('ctl.hint', 'So "đọc thẳng" với "derivedStateOf", rồi xem ghi ngược.', 'Compare "direct read" with "derivedStateOf", then watch the backwards write.')
    m('ctl.which', 'Đoạn mã', 'Snippet')
    for k, vi, en in [('direct', 'Đọc thẳng firstVisibleItemIndex', 'Direct read of firstVisibleItemIndex'), ('derived', 'Bọc trong derivedStateOf', 'Wrapped in derivedStateOf'), ('backwards', 'Ghi ngược count++', 'Backwards write count++')]:
        m('ctl.which.' + k, vi, en)
    m('diagramTitle', 'State, derived state và màn hình', 'State, derived state and the screen')
    m('diagramDesc', 'State nối tới màn hình (đọc trực tiếp) và tới derived state; derived state nối tới màn hình; mũi tên từ màn hình về state là ghi ngược', 'State links to the screen (a direct read) and to the derived state; the derived state links to the screen; the arrow from the screen back to the state is a backwards write')
    for k, vi, en in [('state', 'State (index hoặc count)', 'State (index or count)'), ('derived', 'Derived state (bộ lọc)', 'Derived state (filter)'), ('screen', 'Màn hình', 'Screen')]:
        m('n.' + k, vi, en)
    for k, vi, en in [('recomposed', 'Lần màn hình recompose', 'Screen recompositions'), ('value', 'Giá trị state', 'State value')]:
        m('met.' + k, vi, en)
    for k, vi, en in [('index', 'Giá trị firstVisibleItemIndex', 'firstVisibleItemIndex value'), ('show', 'Giá trị showButton', 'showButton value'), ('rec', 'Số lần recompose', 'Recomposition count'), ('count', 'Giá trị count', 'count value')]:
        m('st.' + k, vi, en)
    S = [
        ('intro.direct', 'Đọc thẳng trong composition', 'A direct read in composition', '`showButton` được tính trong thân composable, nên lần đọc `firstVisibleItemIndex` thuộc scope của màn hình.', '`showButton` is computed in the composable body, so the `firstVisibleItemIndex` read belongs to the screen\'s scope.'),
        ('intro.derived', 'Bọc trong derivedStateOf', 'Wrapped in derivedStateOf', 'Màn hình chỉ đọc `showButton`, một derived state. Derived state tự đọc `firstVisibleItemIndex` và chỉ báo thay đổi khi kết quả Boolean đổi.', 'The screen only reads `showButton`, a derived state. The derived state reads `firstVisibleItemIndex` itself and only reports a change when the Boolean result changes.'),
        ('intro.backwards', 'Ghi ngược trong thân composable', 'A backwards write in the composable body', 'Thân hàm đọc `count` (Text) rồi ghi `count++` ngay sau đó. Nút ghi trong `onClick` là đúng; dòng cuối là lỗi.', 'The body reads `count` (Text) and then writes `count++` right after. The button writing in `onClick` is fine; the last line is the bug.'),
        ('d.scroll', 'Index = {n}: màn hình recompose', 'Index = {n}: the screen recomposes', 'Index đổi nên scope đã đọc nó (màn hình) bị invalidate và chạy lại, dù `showButton` vẫn là true từ lần trước.', 'The index changed, so the scope that read it (the screen) is invalidated and re-runs, even though `showButton` was already true.'),
        ('v.flip', 'Index = {n}: Boolean đổi, màn hình recompose', 'Index = {n}: the Boolean flips, the screen recomposes', '`index > 0` đổi từ false sang true: derived state báo thay đổi, màn hình chạy lại để hiện nút.', '`index > 0` flips from false to true: the derived state reports a change, and the screen re-runs to show the button.'),
        ('v.same', 'Index = {n}: Boolean không đổi', 'Index = {n}: the Boolean does not change', 'Derived state tính lại `index > 0` = true như cũ, nên không invalidate màn hình.', 'The derived state recomputes `index > 0` = true as before, so the screen is not invalidated.'),
        ('bw.first', 'Bấm nút: count = 1, recompose', 'Tap: count = 1, recompose', 'Ghi trong `onClick` là đúng chỗ: một lần ghi, một lần recompose.', 'Writing in `onClick` is the right place: one write, one recomposition.'),
        ('bw.loop', 'Lượt {n}: đọc count rồi ghi count++', 'Pass {n}: reads count, then writes count++', 'Thân hàm vừa đọc `count` rồi ghi nó: state đã đọc bị đổi nên scope lại bị invalidate, và lượt sau lặp lại y hệt.', 'The body reads `count` and then writes it: state already read has changed, so the scope is invalidated again, and the next pass does exactly the same.'),
        ('end.direct', 'Kết thúc: 4 lần recompose', 'The end: 4 recompositions', 'Ba trong bốn lần là thừa: nút đã hiện từ lần đầu.', 'Three out of four are wasted: the button was already shown after the first.'),
        ('end.derived', 'Kết thúc: 1 lần recompose', 'The end: 1 recomposition', 'Đúng một lần, ở lúc nút cần hiện.', 'Exactly once, when the button needs to appear.'),
        ('end.backwards', 'Kết thúc: vòng lặp không dừng', 'The end: a loop that never stops', 'Số đếm tăng mãi; Layout Inspector sẽ cho thấy composable này recompose liên tục.', 'The count keeps rising; the Layout Inspector would show this composable recomposing non-stop.'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('backwards', 'Tài liệu: Compose giả định bạn không bao giờ ghi vào state đã được đọc; ví dụ BadComposable tăng count trong vòng lặp vô hạn. [[src:cp-bestpractices]]', 'The docs: Compose assumes you never write to state that has already been read; the BadComposable example increments count in an infinite loop. [[src:cp-bestpractices]]'),
        ('derived', 'Chương B4 giải thích cơ chế: derived state chỉ invalidate người đọc khi giá trị mới khác giá trị cũ. [[src:cp-bestpractices]]', 'Chapter B4 explains the mechanism: a derived state only invalidates its readers when the new value differs from the old one. [[src:cp-bestpractices]]'),
        ('end.direct', 'Đúng đoạn "anti-pattern" của trang Best practices. [[src:cp-bestpractices]]', 'Exactly the Best practices page\'s anti-pattern. [[src:cp-bestpractices]]'),
        ('end.derived', 'Từ Compose Runtime 1.13 còn có `computedStateOf`: tính lại mỗi lần đọc, không cache; tài liệu khuyên dùng cho điều kiện nhẹ như vị trí cuộn, và `derivedStateOf` khi phép tính đắt hoặc được đọc nhiều lần. [[src:cp-bestpractices]]', 'Since Compose Runtime 1.13 there is also `computedStateOf`: re-evaluated on every read, not cached; the docs suggest it for light conditions such as scroll offsets, and `derivedStateOf` when the calculation is expensive or read several times. [[src:cp-bestpractices]]'),
        ('end.backwards', 'Luật: không ghi state trong composition; ghi trong lambda sự kiện như `onClick`. [[src:cp-bestpractices]]', 'The rule: never write state in composition; write in event lambdas such as `onClick`. [[src:cp-bestpractices]]')]:
        m('co.' + k, vi, en)
    a('cap.perf', 'State ở trái, màn hình ở phải, derivedStateOf ở giữa. Mũi tên state → màn hình là đọc thẳng; state → derived → màn hình là đọc qua bộ lọc; màn hình → state là ghi ngược. Chỉ số đếm số lần màn hình recompose.', 'State on the left, the screen on the right, derivedStateOf in the middle. The state → screen arrow is a direct read; state → derived → screen is a filtered read; screen → state is a backwards write. The metrics count screen recompositions.')

    # ---------------- chương PF (mới) ----------------
    C = 'pf'
    a(C + '.title', 'Hiệu năng và debug: đo trước, sửa sau', 'Performance and debugging: measure first, then fix')
    a(C + '.essence',
      'Chương tổng hợp: các cơ chế đã học (skip và stability ở B8, đọc state theo phase ở B7, derived state ở B4, lazy list ở LZ) gặp nhau khi một màn hình giật. Việc đầu tiên không phải là sửa mã mà là đo đúng: bản release với R8, có Baseline Profile, rồi mới nhìn số liệu.\n'
      'Năm thực hành của tài liệu: `remember` phép tính đắt; key và contentType cho lazy layout; `derivedStateOf`/`computedStateOf` để lọc recompose; hoãn lần đọc state (lambda, modifier dạng lambda); và không bao giờ ghi ngược vào state đã đọc.\n'
      'Công cụ: số đếm recompose/skip của Layout Inspector để định hướng, composition tracing và recomposition tracing để thấy composable trong system trace, Macrobenchmark để xác nhận.',
      'A synthesis chapter: the mechanisms learned so far (skipping and stability in B8, phased state reads in B7, derived state in B4, lazy lists in LZ) meet when a screen stutters. The first step is not to change code but to measure correctly: a release build with R8, with a Baseline Profile, then look at numbers.\n'
      'The docs\' five practices: `remember` expensive calculations; keys and contentType for lazy layouts; `derivedStateOf`/`computedStateOf` to filter recompositions; defer state reads (lambdas, lambda modifiers); and never write backwards to state already read.\n'
      'Tools: the Layout Inspector\'s recomposition/skip counts to orient yourself, composition tracing and recomposition tracing to see composables in a system trace, and Macrobenchmark to confirm.')
    a(C + '.goal.g1', 'Đã thấy sự kiện đầu tiên và màn hình có recompose hay không', 'Saw the first event and whether the screen recomposed')
    a(C + '.goal.g2', 'Đã chạy một đoạn mã tới cuối', 'Ran one snippet to the end')
    a(C + '.sim.runtime.perf', 'Đếm recomposition', 'Counting recompositions')

    S = 'hook'
    a(C + '.sec.%s.title' % S, 'Đoán trước khi đọc', 'Predict before reading')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'predict', 'App cuộn giật khi chạy từ Android Studio (bản debug). Bạn nên làm gì TRƯỚC khi sửa mã?', 'The app scrolls with jank when run from Android Studio (a debug build). What should you do BEFORE changing code?')
    B(C, S, 1, 'ans', 'Chạy bản release có bật R8, và có Baseline Profile. Tài liệu: chế độ debug có ích để tìm nhiều lỗi nhưng có chi phí hiệu năng và che các vấn đề khác; Baseline Profile giúp code chạy nhanh hơn khoảng 30% từ lần mở đầu tiên với đường đi được đưa vào profile. Nhiều "giật" ở bản debug không còn ở bản release. [[src:cp-performance]] [[src:cp-baseline]]', 'Run a release build with R8 enabled, with a Baseline Profile. The docs: debug mode helps spot many problems but has a performance cost and hides other issues; Baseline Profiles make included code paths run about 30% faster from the first launch. Much of the "jank" in a debug build is gone in release. [[src:cp-performance]] [[src:cp-baseline]]')

    S = 'config'
    a(C + '.sec.%s.title' % S, 'Đo cho đúng: release, R8, Baseline Profile', 'Measuring correctly: release, R8, Baseline Profiles')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Trang Performance mở đầu bằng hai mục cấu hình:\n• Build bản release với R8: R8 tối ưu và thu gọn mã.\n• Dùng Baseline Profile. Compose là một thư viện, nên mã của nó phải được nạp khi app mở, rồi thông dịch hay JIT khi cần. Baseline Profile liệt kê lớp và hàm của các luồng quan trọng, đi kèm APK/AAB. Khi cài, ART biên dịch trước (AOT) đoạn mã đó. Theo trang Baseline Profiles, các đường đi có trong profile chạy nhanh hơn khoảng 30% ngay từ lần mở đầu tiên.\nCompose có sẵn một profile, nhưng chỉ cho mã của chính thư viện. App nên tạo profile riêng, bằng Macrobenchmark cho các luồng người dùng quan trọng [[src:cp-performance]] [[src:cp-baseline]].\nQuy tắc dễ nhớ: đừng bao giờ đánh giá hiệu năng Compose trên bản debug.',
      "The Performance page opens with two configuration items:\n• Build a release build with R8: R8 optimises and shrinks the code.\n• Use a Baseline Profile. Compose is a library, so its code has to be loaded when the app opens, then interpreted or JIT-compiled when needed. A Baseline Profile lists the classes and methods of critical journeys and ships with the APK/AAB. On installation, ART compiles that code ahead of time (AOT). Per the Baseline Profiles page, paths included in the profile run about 30% faster from the very first launch.\nCompose ships a profile, but only for the library's own code. Apps should create their own, using Macrobenchmark over the critical user journeys [[src:cp-performance]] [[src:cp-baseline]].\nRule of thumb: never judge Compose performance on a debug build.")
    B(C, S, 2, 'note', 'Trang Performance có bảng so jank khi cuộn giữa Compose và View theo từng phiên bản, và ghi: từ Compose 1.9.0, Compose ngang View về jank khi cuộn trên benchmark của họ. Site đối chiếu ở Compose 1.13.0 [[src:cp-performance]].',
      'The Performance page has a table comparing scroll jank between Compose and Views version by version, and states that since Compose 1.9.0, Compose matches Views on scroll jank in their benchmark. The site is checked against Compose 1.13.0 [[src:cp-performance]].')
    B(C, S, 2, 'kind', 'source')

    S = 'remember'
    a(C + '.sec.%s.title' % S, 'remember phép tính đắt, nhưng đừng remember mọi thứ', 'remember expensive work, but not everything')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Composable có thể chạy rất thường xuyên, tới mức mỗi frame của animation. Sắp xếp danh sách ngay trong `items(contacts.sortedWith(comparator))` nghĩa là sắp xếp lại mỗi lần recompose.\nHãy bọc trong `remember(contacts, comparator) { … }`, với MỌI đầu vào làm key. Nhưng `remember` so key bằng `equals` mỗi lượt. Tài liệu đưa phản ví dụ `remember(contacts) { contacts.firstOrNull()?.name.orEmpty() }`: so một list lớn còn tốn hơn chính phép tính.\nTốt nhất là đưa phép tính ra khỏi composable, ví dụ vào ViewModel [[src:cp-bestpractices]].\nQuy tắc dễ nhớ: việc nặng không thuộc về thân composable; `remember` chỉ là cách chữa tạm.',
      'Composables can run very often, as often as every frame of an animation. Sorting a list right inside `items(contacts.sortedWith(comparator))` means sorting again on every recomposition.\nWrap it in `remember(contacts, comparator) { … }`, with EVERY input as a key. But `remember` compares keys with `equals` on every pass. The docs give a counter-example, `remember(contacts) { contacts.firstOrNull()?.name.orEmpty() }`: comparing a large list costs more than the calculation itself.\nBest of all is to move the calculation out of the composable, for example into a ViewModel [[src:cp-bestpractices]].\nRule of thumb: heavy work does not belong in a composable body; `remember` is only a stopgap.')
    B(C, S, 2, 'kt', 'val sortedContacts = remember(contacts, comparator) {   // mọi đầu vào là key\n    contacts.sortedWith(comparator)\n}\nLazyColumn(modifier) {\n    items(sortedContacts, key = { it.id }) { contact -> ContactRow(contact) }\n}', 'val sortedContacts = remember(contacts, comparator) {   // every input is a key\n    contacts.sortedWith(comparator)\n}\nLazyColumn(modifier) {\n    items(sortedContacts, key = { it.id }) { contact -> ContactRow(contact) }\n}')
    B(C, S, 3, 'p', 'Với lazy layout, trang Best practices thêm những luật cụ thể hơn LZ:\n• Key duy nhất, xác định, và lưu được trong Bundle: ưu tiên `Int`, `Long`, `String`; KHÔNG dùng chỉ số hay `hashCode()`.\n• Luôn đặt `contentType` cho danh sách có nhiều loại mục.\n• Dùng `itemsIndexed` thay vì `list.indexOf(item)` bên trong `items` (cách sau quét O(N²)).\n• Đọc `LocalContext.current`, `LocalDensity.current` ở cha, đừng đọc trong từng mục.\n• Danh sách nhỏ cố định (khoảng 1 tới 10 mục) thì dùng `Row`/`Column`.\n• Mục lớn hơn nửa viewport thì chỉnh `cacheWindow` [[src:cp-bestpractices]].',
      'For lazy layouts, the Best practices page adds rules more specific than LZ:\n• Keys that are unique, deterministic and Bundle-saveable: prefer `Int`, `Long`, `String`; NEVER indices or `hashCode()`.\n• Always set `contentType` for lists with several kinds of items.\n• Use `itemsIndexed` instead of `list.indexOf(item)` inside `items` (the latter is an O(N²) scan).\n• Read `LocalContext.current` and `LocalDensity.current` in the parent, not in each item.\n• Use `Row`/`Column` for small fixed lists (about 1 to 10 items).\n• Tune `cacheWindow` for items larger than half the viewport [[src:cp-bestpractices]].')

    S = 'derive'
    a(C + '.sec.%s.title' % S, 'Lọc recomposition: derivedStateOf và computedStateOf', 'Filtering recomposition: derivedStateOf and computedStateOf')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Ví dụ của tài liệu (và của LZ): đọc `listState.firstVisibleItemIndex > 0` thẳng trong composition làm màn hình recompose mỗi lần mục đầu tiên đổi, trong khi thứ cần chỉ là một Boolean. `remember { derivedStateOf { … } }` cache kết quả và chỉ báo khi Boolean đổi.\nTừ Compose Runtime 1.13 có thêm `computedStateOf` (file `ComputedState.kt` có trong thư mục runtime ở commit ghim). Nó tính lại mỗi lần đọc, không cache. Tài liệu khuyên dùng nó cho điều kiện cơ bản và dẫn xuất nhẹ như vị trí cuộn; còn `derivedStateOf` cho bản Compose cũ hơn, hoặc khi phép tính đắt và được đọc nhiều lần mỗi lượt.\nĐừng đưa state được đọc bên trong làm key của `remember`: tài liệu nói việc đó tạo lại `DerivedState` mỗi lần state đổi, và làm mất skip. Mô phỏng ngay dưới đếm số lần recompose [[src:cp-bestpractices]].',
      "The docs' example (and LZ's): reading `listState.firstVisibleItemIndex > 0` directly in composition recomposes the screen every time the first item changes, when all that is needed is a Boolean. `remember { derivedStateOf { … } }` caches the result and only reports when the Boolean changes.\nSince Compose Runtime 1.13 there is also `computedStateOf` (the `ComputedState.kt` file is in the runtime directory at the pinned commit). It re-evaluates on every read, without caching. The docs suggest it for basic conditions and light derivations such as scroll offsets; and `derivedStateOf` for older Compose versions, or when the calculation is expensive and read several times per pass.\nDo not pass the state read inside as a key of `remember`: the docs say that recreates the `DerivedState` on every state change, and prevents skipping. The simulation just below counts recompositions [[src:cp-bestpractices]].")
    B(C, S, 2, 'note', 'Site chưa đọc mã `ComputedState.kt` để giải thích cơ chế bên trong của `computedStateOf`; phần trên chỉ dựa vào trang Best practices [[src:cp-bestpractices]].',
      'The site has not read the `ComputedState.kt` code to explain how `computedStateOf` works inside; the text above relies only on the Best practices page [[src:cp-bestpractices]].')
    B(C, S, 2, 'kind', 'source')

    S = 'defer'
    a(C + '.sec.%s.title' % S, 'Hoãn lần đọc state', 'Deferring state reads')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Ví dụ Jetsnack của tài liệu đi qua ba bước, nối thẳng với B7:\n1. `Title(snack, scroll.value)`: giá trị được đọc ở `SnackDetail`, nên cả scope của Box recompose cho mỗi pixel cuộn.\n2. Truyền một lambda `Title(snack) { scroll.value }`: lần đọc dời vào trong `Title`, và scope recompose gần nhất giờ là `Title`.\n3. Dùng modifier dạng lambda `Modifier.offset { IntOffset(0, scrollProvider()) }`: lần đọc nằm ở layout, nên Compose bỏ qua hẳn composition.\nTương tự, một màu đang animate mà đọc trong `drawBehind { drawRect(color) }` thì bỏ qua cả composition lẫn layout [[src:cp-bestpractices]] [[src:cp-phases]].\nQuy tắc dễ nhớ: hãy nghi ngờ nếu bạn gây recomposition chỉ để layout hay vẽ lại.',
      "The docs' Jetsnack example goes through three steps, tying straight back to B7:\n1. `Title(snack, scroll.value)`: the value is read in `SnackDetail`, so the Box's whole scope recomposes for every pixel scrolled.\n2. Pass a lambda, `Title(snack) { scroll.value }`: the read moves inside `Title`, and the nearest recomposition scope is now `Title`.\n3. Use a lambda modifier, `Modifier.offset { IntOffset(0, scrollProvider()) }`: the read happens in layout, so Compose skips composition entirely.\nLikewise, an animating colour read inside `drawBehind { drawRect(color) }` skips both composition and layout [[src:cp-bestpractices]] [[src:cp-phases]].\nRule of thumb: be suspicious if you are causing recomposition just to re-layout or redraw.")
    B(C, S, 2, 'kt', '@Composable\nprivate fun Title(snack: Snack, scrollProvider: () -> Int) {\n    Column(\n        modifier = Modifier.offset { IntOffset(x = 0, y = scrollProvider()) }   // đọc ở layout\n    ) { /* … */ }\n}\n\n// màu animate: đọc ở draw\nBox(Modifier.fillMaxSize().drawBehind { drawRect(color) })', '@Composable\nprivate fun Title(snack: Snack, scrollProvider: () -> Int) {\n    Column(\n        modifier = Modifier.offset { IntOffset(x = 0, y = scrollProvider()) }   // read in layout\n    ) { /* … */ }\n}\n\n// an animated colour: read in draw\nBox(Modifier.fillMaxSize().drawBehind { drawRect(color) })')

    S = 'backwards'
    a(C + '.sec.%s.title' % S, 'Không ghi ngược', 'No backwards writes')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Compose giả định bạn không bao giờ ghi vào một state đã được đọc trong cùng lượt composition. `BadComposable` của tài liệu đọc `count` trong `Text("$count")` rồi `count++` ngay sau đó. Mỗi lượt recompose lại ghi vào state vừa đọc, làm scope bị invalidate thêm lần nữa, và số đếm cứ tăng trong một vòng lặp vô hạn.\nLuật: không ghi state trong composition; ghi trong lambda sự kiện như `onClick`. Liên hệ với B7: ghi state trong `onSizeChanged` để composition đọc chính là phiên bản "qua nhiều frame" của cùng vấn đề [[src:cp-bestpractices]] [[src:cp-phases]].\nQuy tắc dễ nhớ: thân composable chỉ được ĐỌC state, không được GHI.',
      'Compose assumes you never write to a state that was already read in the same composition pass. The docs\' `BadComposable` reads `count` in `Text("$count")` and then does `count++` right after. Every recomposition writes to the state it just read, invalidating the scope once more, and the count keeps rising in an infinite loop.\nThe rule: never write state in composition; write it in event lambdas such as `onClick`. Link to B7: writing state in `onSizeChanged` for composition to read is the "across several frames" version of the same problem [[src:cp-bestpractices]] [[src:cp-phases]].\nRule of thumb: a composable body may only READ state, never WRITE it.')

    S = 'tools'
    a(C + '.sec.%s.title' % S, 'Công cụ: Layout Inspector, tracing, benchmark', 'Tools: the Layout Inspector, tracing, benchmarks')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Layout Inspector có hai cột: số lần composition và số lần skip của từng node. Bật bằng "Show Recomposition Counts" trong View Options của Component Tree; cần API 29+ và Compose 1.2.0+. Có nút Reset, và composable nào recompose nhiều thì được tô gradient đậm hơn. Nhớ giữ nguyên các file `META-INF/androidx.compose.*.version` trong APK.\nNhưng trang Tools nói thẳng: số đếm recompose không thay được benchmark. Luôn xác nhận bằng composition tracing và Macrobenchmark [[src:cp-tooling-debug]] [[src:book-kunneth]].',
      'The Layout Inspector has two columns: the number of compositions and the number of skips for each node. Turn them on with "Show Recomposition Counts" in the Component Tree\'s View Options; it needs API 29+ and Compose 1.2.0+. There is a Reset button, and composables that recompose more get a stronger gradient. Remember to keep the `META-INF/androidx.compose.*.version` files in the APK.\nBut the Tools page says it plainly: recomposition counts are no substitute for benchmarks. Always confirm with composition tracing and Macrobenchmark [[src:cp-tooling-debug]] [[src:book-kunneth]].')
    B(C, S, 2, 'p', 'Composition tracing đưa tên composable vào system trace: vừa nhẹ như system trace, vừa chi tiết gần bằng method trace. Cần `androidx.compose.runtime:runtime-tracing`, Compose UI và compiler 1.3.0+, và thiết bị API 30+. Ghi bằng Profiler (CPU, System Trace) hoặc Perfetto từ dòng lệnh; nhấp đúp một composable trong biểu đồ để nhảy tới mã nguồn. Muốn thời gian chính xác, app nên `profileable` và không `debuggable`.\nRecomposition tracing (runtime-tracing 1.13.0+, API 29+) còn cho thấy lần đọc hay ghi state nào đã gây recompose, nhưng tốn hơn. Tài liệu dặn: dùng nó để debug recomposition, không dùng để đo hiệu năng [[src:cp-tracing]].',
      'Composition tracing puts composable names into system traces: as light as system tracing, with detail close to method tracing. It needs `androidx.compose.runtime:runtime-tracing`, Compose UI and compiler 1.3.0+, and an API 30+ device. Record with the Profiler (CPU, System Trace) or Perfetto from the command line; double-click a composable in the chart to jump to its source. For accurate timing, the app should be `profileable` and not `debuggable`.\nRecomposition tracing (runtime-tracing 1.13.0+, API 29+) also shows which state read or write caused a recomposition, but costs more. The docs say: use it to debug recompositions, not to measure performance [[src:cp-tracing]].')
    B(C, S, 3, 'p', 'Một quy trình gợi ý, gom từ các trang trên và B8:\n1. Tái hiện trên bản release, có R8 và Baseline Profile.\n2. Đo bằng Macrobenchmark hoặc trace, để biết có thật sự có vấn đề không, và ở đâu.\n3. Dùng số đếm recompose và recomposition tracing để tìm ai recompose quá nhiều.\n4. Sửa theo thứ tự từ rẻ tới đắt: hoãn lần đọc, derived state, key và contentType, giữ tham chiếu tham số ổn định; annotation stability để sau cùng.\n5. Đo lại [[src:cp-performance]] [[src:cp-tooling-debug]] [[src:cp-stability-fix]].\nQuy tắc dễ nhớ: đo, sửa, rồi đo lại; không đo thì không sửa.',
      'A suggested workflow, gathered from the pages above and B8:\n1. Reproduce on a release build, with R8 and a Baseline Profile.\n2. Measure with Macrobenchmark or traces, to know whether there really is a problem, and where.\n3. Use recomposition counts and recomposition tracing to find who recomposes too much.\n4. Fix in order from cheap to expensive: defer reads, derived state, keys and contentType, stable parameter references; stability annotations last.\n5. Measure again [[src:cp-performance]] [[src:cp-tooling-debug]] [[src:cp-stability-fix]].\nRule of thumb: measure, fix, then measure again; no measuring, no fixing.')

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp', 'Common bugs')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', 'Layout Inspector cho thấy một composable recompose liên tục khi màn hình đứng yên, CPU luôn bận.', 'The Layout Inspector shows a composable recomposing non-stop while the screen is idle, and the CPU is always busy.')
    B(C, S, 1, 'cause', 'Ghi ngược: thân composable ghi vào state mà chính nó (hoặc một phần trước đó trong lượt) đã đọc, ví dụ đặt cờ "đã hiện" ngay trong composition.', 'A backwards write: the composable body writes to state that it (or something earlier in the pass) already read, such as setting a "shown" flag right in composition.')
    B(C, S, 1, 'fix', 'Chuyển việc ghi vào lambda sự kiện, hoặc vào effect (`LaunchedEffect`, `SideEffect`; chương EF) nếu thật cần chạy sau composition. [[src:cp-bestpractices]]', 'Move the write into an event lambda, or into an effect (`LaunchedEffect`, `SideEffect`; chapter EF) if it really must run after composition. [[src:cp-bestpractices]]')
    B(C, S, 2, 'bug', 'Màn hình danh sách liên hệ giật mỗi khi một ô tìm kiếm ở trên đổi chữ, dù danh sách không đổi.', 'A contacts screen stutters whenever a search box above changes text, even though the list does not change.')
    B(C, S, 2, 'cause', '`items(contacts.sortedWith(comparator))`: mỗi lần màn hình recompose vì ô tìm kiếm, danh sách lại được sắp xếp.', '`items(contacts.sortedWith(comparator))`: every time the screen recomposes because of the search box, the list is sorted again.')
    B(C, S, 2, 'fix', '`remember(contacts, comparator) { contacts.sortedWith(comparator) }`, hoặc sắp xếp trong ViewModel. [[src:cp-bestpractices]]', '`remember(contacts, comparator) { contacts.sortedWith(comparator) }`, or sort in the ViewModel. [[src:cp-bestpractices]]')
    B(C, S, 3, 'bug', 'Sau khi "tối ưu" bằng cách thêm `@Immutable` cho mọi lớp và đổi mọi `List` thành `ImmutableList`, benchmark cuộn còn tệ hơn.', 'After "optimising" by adding `@Immutable` to every class and turning every `List` into `ImmutableList`, the scroll benchmark got worse.')
    B(C, S, 3, 'cause', 'Dưới strong skipping, `List` thường được so bằng `===` (rẻ); `ImmutableList` và lớp có annotation chạy `equals` từng phần tử mỗi lượt (chương B8).', 'Under strong skipping, a plain `List` is compared with `===` (cheap); `ImmutableList` and annotated classes run element-by-element `equals` every pass (chapter B8).')
    B(C, S, 3, 'fix', 'Hoàn tác, giữ tham chiếu ổn định, và chỉ đổi stability khi benchmark chỉ ra nút thắt. [[src:cp-stability-fix]]', 'Revert, keep references stable, and change stability only when a benchmark points to a bottleneck. [[src:cp-stability-fix]]')

    S = 'exercises'
    a(C + '.sec.%s.title' % S, 'Bài tập', 'Exercises')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ex', 'Một thanh tiến độ đọc bài phải rộng theo `scrollState.value`. Viết sao cho cuộn không gây recomposition.', 'A reading-progress bar must be as wide as `scrollState.value` suggests. Write it so scrolling causes no recomposition.')
    B(C, S, 1, 'hint', 'Đọc ở phase draw.', 'Read in the draw phase.')
    B(C, S, 1, 'solkt', 'Box(\n    Modifier\n        .fillMaxWidth()\n        .height(4.dp)\n        .drawBehind {\n            val fraction = scrollState.value / scrollState.maxValue.coerceAtLeast(1).toFloat()\n            drawRect(Color.Blue, size = size.copy(width = size.width * fraction))\n        }\n)')
    B(C, S, 1, 'sol', 'Lần đọc `scrollState.value` nằm trong `drawBehind`, nên mỗi lần cuộn chỉ vẽ lại (chương B7).', 'The `scrollState.value` read lives inside `drawBehind`, so each scroll only redraws (chapter B7).')
    B(C, S, 2, 'ex', 'Trong mô phỏng, nếu cuộn thêm tới index 10 rồi quay về 0, bản "đọc thẳng" và bản "derivedStateOf" recompose tổng cộng bao nhiêu lần (tính từ index 0, mỗi bước 1)?', 'In the simulation, if you scroll on to index 10 and then back to 0, how many recompositions do the "direct read" and "derivedStateOf" versions make in total (starting from index 0, steps of 1)?')
    B(C, S, 2, 'hint', 'Đếm số lần index đổi, và số lần Boolean `index > 0` đổi.', 'Count how often the index changes, and how often the Boolean `index > 0` changes.')
    B(C, S, 2, 'sol', 'Index đổi 20 lần (0→10 rồi 10→0) nên bản đọc thẳng recompose 20 lần. Boolean chỉ đổi hai lần (0→1 và 1→0) nên bản derivedStateOf recompose 2 lần.', 'The index changes 20 times (0→10 then 10→0), so the direct version recomposes 20 times. The Boolean only flips twice (0→1 and 1→0), so the derivedStateOf version recomposes twice.')

    S = 'recall'
    a(C + '.sec.%s.title' % S, 'Tự trả lời', 'Answer it yourself')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ask', 'Hai cấu hình phải có trước khi đo hiệu năng?', 'Two configurations needed before measuring performance?')
    B(C, S, 1, 'ans', 'Bản release với R8, và Baseline Profile.', 'A release build with R8, and a Baseline Profile.')
    B(C, S, 2, 'ask', 'Vì sao số đếm recompose không đủ để kết luận?', 'Why are recomposition counts not enough to conclude anything?')
    B(C, S, 2, 'ans', 'Chúng không đo thời gian; một skip có equals đắt có thể tốn hơn một recompose rẻ. Cần trace và Macrobenchmark.', 'They do not measure time; a skip with an expensive equals can cost more than a cheap recomposition. Traces and Macrobenchmark are needed.')
    B(C, S, 3, 'ask', 'Ghi ngược là gì?', 'What is a backwards write?')
    B(C, S, 3, 'ans', 'Ghi vào state đã được đọc trong cùng lượt composition, gây vòng lặp recompose.', 'Writing to state already read in the same composition pass, causing a recomposition loop.')
    for q, qv, qe, av, ae, wv, we in [
        ('q1', 'Baseline Profile cải thiện tốc độ chạy code khoảng bao nhiêu theo tài liệu?', 'By about how much do Baseline Profiles improve code execution speed, per the docs?',
         'Khoảng 30% từ lần mở đầu tiên.', 'About 30% from the first launch.', 'Cho các đường đi có trong profile, nhờ tránh thông dịch và JIT.', 'For included code paths, by avoiding interpretation and JIT.'),
        ('q2', 'Màu animate mỗi frame nên đọc ở đâu?', 'Where should a colour animated every frame be read?',
         'Trong drawBehind (phase draw).', 'Inside drawBehind (the draw phase).', 'Bỏ qua composition và layout.', 'It skips composition and layout.'),
        ('q3', 'Có nên dùng key là chỉ số hay hashCode()?', 'Should keys be indices or hashCode()?',
         'Không.', 'No.', 'Key phải duy nhất, xác định, lưu được trong Bundle.', 'Keys must be unique, deterministic and Bundle-saveable.'),
        ('q4', 'Recomposition tracing dùng để làm gì?', 'What is recomposition tracing for?',
         'Debug ai gây recompose, không để đo hiệu năng.', 'Debugging what causes recomposition, not measuring performance.', 'Nó tốn hơn composition tracing.', 'It has more overhead than composition tracing.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)
